// Helpers para formatação
const num = (val) => {
  const str = String(val).split('.')[0];
  return str.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};

const pct = (val) => {
  const fixed = Number(val).toFixed(2).replace('.', ',');
  return (val >= 0 ? '+' : '') + fixed + '%';
};

const seta = (val) => (val >= 0 ? '▲' : '▼');

// Parse cotações
const cot = $input.all()[0].json.USDBRL || {};
const btc = $input.all()[0].json.BTCBRL || {};
const eth = $input.all()[0].json.ETHBRL || {};

// Parse Ibovespa (BOVA11 como proxy)
let iboChange = 'N/A';
try {
  const iboData = $input.all()[1].json.quoteSummary?.result?.[0]?.price;
  if (iboData) {
    const regularMarketChangePercent = iboData.regularMarketChangePercent?.raw || 0;
    iboChange = pct(regularMarketChangePercent);
  }
} catch (e) {
  iboChange = 'Erro';
}

// Parse ações: top 3 e bottom 3 por mudança percentual
let altas = 'N/A';
let baixas = 'N/A';
try {
  const acoes = $input.all()[2].json.stocks || [];
  if (acoes.length >= 6) {
    const sorted = [...acoes].sort((a, b) => (b.regularMarketChangePercent || 0) - (a.regularMarketChangePercent || 0));
    const topAltas = sorted.slice(0, 3);
    const topBaixas = sorted.slice(-3).reverse();

    altas = topAltas.map(a => `${a.stock} ${pct(a.regularMarketChangePercent)} ${seta(a.regularMarketChangePercent)}`).join('\n');
    baixas = topBaixas.map(a => `${a.stock} ${pct(a.regularMarketChangePercent)} ${seta(a.regularMarketChangePercent)}`).join('\n');
  }
} catch (e) {
  altas = 'Erro';
  baixas = 'Erro';
}

// Parse notícias
let noticias = 'N/A';
try {
  const news = $input.all()[3].json.articles || [];
  if (news.length > 0) {
    noticias = news.slice(0, 3).map((n, i) => `${i + 1}. ${n.title}`).join('\n');
  }
} catch (e) {
  noticias = 'Erro';
}

// Formatar data em português
const agora = new Date();
const diasSemana = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
const meses = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const diaSemana = diasSemana[agora.getDay()];
const dia = agora.getDate();
const mes = meses[agora.getMonth()];

const mensagem = `📊 *BRIEFING MATUTINO* — ${diaSemana.toUpperCase()}, ${dia} de ${mes}\n\n💱 *COTAÇÕES*\nUSD/BRL: ${cot.bid || 'N/A'}\nBTC/BRL: R$ ${num(btc.bid || 0)}\nETH/BRL: R$ ${num(eth.bid || 0)}\n\n📈 *ÍNDICE*\nIbovespa (BOVA11): ${iboChange}\n\n🚀 *ALTAS*\n${altas}\n\n📉 *BAIXAS*\n${baixas}\n\n📰 *DESTAQUES*\n${noticias}`;

return { mensagem, timestamp: new Date().toISOString() };
